			ewreg <= 0;
			em2reg <= 0;
			ewmem <= 0;
			ealuc <= 0;
			ealuimm <= 0;
			ern0 <= 0;
			eshift <= 0;
			ejal <= 0;
			ea <= 0;
			eb <= 0;
			eimm <= 0;
			epc4 <= 0;
			esa <= 0;
		end
		else
		begin
			ewreg <= dwreg;
			em2reg <= dm2reg;
			ewmem <= dwmem;
			ealuc <= daluc;
			ealuimm <= daluimm;
			ern0 <= drn;
			eshift <= dshift;
			ejal <= djal;
			ea <= da;
			eb <= db;
			eimm <= dimm;
			epc4 <= dpc4;
			esa <= dsa;
