module dualportram #( parameter WIDTH = 64, parameter DEPTH = 6 ) ( input wire clk_a, input wire we_a, input wire [DEPTH-1:0] addr_a, input wire [WIDTH-1:0] din_a, output reg [WIDTH-1:0] dout_a, input wire clk_b, input wire we_b, input wire [DEPTH-1:0] addr_b, input wire [WIDTH-1:0] din_b, output reg [WIDTH-1:0] dout_b );
reg [WIDTH-1:0] memarray [0:DEPTH-1];
always @(posedge clk_a) begin
	if (we_a) begin
		memarray[addr_a] <= din_a;
		dout_a <= din_a;
	end
	else begin
		dout_a <= memarray[addr_a];
	end
end
always @(posedge clk_b) begin
	if (we_b) begin
		memarray[addr_b] <= din_b;
		dout_b <= din_b;
	end
	else begin
		dout_b <= memarray[addr_b];
	end
end
endmodule

