module shift_16_9 (
    input [15:0] x,
    input [15:0] y,
    input [1:0] shiftAlufn,
    output reg [15:0] shiftOut
  );
reg [15:0] temp;
  always @* begin
    case (shiftAlufn)
      2'b00: temp = x << y[3:0];
      2'b01: temp = x >> y[3:0];
      2'b10: temp = x << {1'b0, y[3:0]};
      2'b11: temp = x >>> {1'b0, y[3:0]};
      default: temp = 16'd0;
    endcase
  end
  assign shiftOut = temp;
endmodule

module AXI_WRITE_DATA_CHANNEL_model(
input wire clk,
input wire resetn,
input wire [31:0] data,
input wire go,
output reg done,
output wire [31:0] WDATA,
output reg [3:0] WSTRB,
output reg WVALID,
input wire WREADY
); 

parameter [31:0] IDLE=4'b0000;
parameter [31:0] RUNNING=4'b0001;
parameter [31:0] COMPLETE=4'b0010;
parameter [31:0] RESET=4'b0011;
reg [31:0] current_state;
reg [31:0] next_state;
  always @(posedge clk, posedge resetn) begin
    if((resetn == 1'b0)) begin
      current_state <= RESET;
    end else begin
      current_state <= next_state;
    end
  end
  always @(current_state, go, WREADY) begin
    case(current_state)
    RESET : begin
      next_state <= IDLE;
    end
    IDLE : begin
      if((go == 1'b1)) begin
        next_state <= RUNNING;
      end
      else begin
        next_state <= IDLE;
      end
    end
    RUNNING : begin
      if((WREADY == 1'b1)) begin
        next_state <= COMPLETE;
      end
      else begin
        next_state <= RUNNING;
      end
    end
    COMPLETE : begin
      next_state <= IDLE;
    end
    default : begin
      next_state <= IDLE;
    end
    endcase
  end
  always @(current_state, go, WREADY) begin
    case(current_state)
    RESET : begin
      done <= 1'b0;
      WDATA <= 32'h00000000;
      WSTRB <= 4'h0;
      WVALID <= 1'b0;
    end
    IDLE : begin
      done <= 1'b0;
      WDATA <= 32'h00000000;
      WSTRB <= 4'h0;
      WVALID <= 1'b0;
    end
    RUNNING : begin
      done <= 1'b0;
      WDATA <= data;
      WSTRB <= 4'hF;
      WVALID <= 1'b1;
    end
    COMPLETE : begin
      done <= 1'b1;
      WDATA <= 32'h00000000;
      WSTRB <= 4'h0;
      WVALID <= 1'b0;
    end
    default : begin
      done <= 1'b0;
      WDATA <= 32'h00000000;
      WSTRB <= 4'h0;
      WVALID <= 1'b0;
    end
    endcase
  end
endmodule

