module fifo36_demux
  #(parameter match_data = 0,
    parameter match_mask = 0)
   (input clk, input reset, input clear,
    input [35:0] data_i, input src_rdy_i, output dst_rdy_o,
    output [35:0] data0_o, output src0_rdy_o, input dst0_rdy_i,
    output [35:0] data1_o, output src1_rdy_o, input dst1_rdy_i);
localparam IDLE = 0, DATA0 = 1, DATA1 = 2;
   reg [1:0] state, next_state;
   reg src0_rdy, src1_rdy;
   reg eof;
   wire [35:0] data0, data1;
   assign data0 = (state == DATA0) ? data_i : 0;
   assign data1 = (state == DATA1) ? data_i : 0;
   assign data0_o = data0;
   assign data1_o = data1;
   assign src0_rdy_o = src0_rdy;
   assign src1_rdy_o = src1_rdy;
   assign dst_rdy_o = (state == DATA0) ? dst0_rdy_i : dst1_rdy_i;
   always @(posedge clk) begin
      if (reset) begin
         state <= IDLE;
      end else if (clear) begin
         state <= IDLE;
      end else begin
         state <= next_state;
      end
   end
   always @(state, data_i, match_data, match_mask) begin
      src0_rdy = 0;
      src1_rdy = 0;
      eof = 0;
      case (state)
         IDLE: begin
            if (data_i[35:0] == match_data && data_i[35:0] == match_mask) begin
               next_state <= DATA0;
            end
         end
         DATA0: begin
            if (data_i[35:0] == match_data && data_i[35:0] == match_mask) begin
               next_state <= DATA0;
            end else begin
               next_state <= IDLE;
            end
            src0_rdy = 1;
            src1_rdy = 0;
            eof = 0;
         end
         DATA1: begin
            if (data_i[35:0] == match_data && data_i[35:0] == match_mask) begin
               next_state <= DATA1;
            end else begin
               next_state <= IDLE;
            end
            src0_rdy = 0;
            src1_rdy = 1;
            eof = 0;
         end
         default: begin
            next_state <= IDLE;
         end
      endcase
   end
endmodule

module branch_ctrl(
	input [31:0]	data_rs1	,
	input [31:0]	data_rs2	,
	input [2:0]		funct3		,
	output	reg		jmpb
);
always @(*) begin
		case (funct3)
			4'b0000: jmpb = (data_rs1 == data_rs2);
			4'b0001: jmpb = (data_rs1 != data_rs2);
			4'b0010: jmpb = (data_rs1 < data_rs2);
			4'b0011: jmpb = (data_rs1 > data_rs2);
			4'b0100: jmpb = (data_rs1 < $signed(data_rs2));
			4'b0101: jmpb = (data_rs1 > $signed(data_rs2));
			4'b0110: jmpb = (data_rs1 < $unsigned(data_rs2));
			4'b0111: jmpb = (data_rs1 > $unsigned(data_rs2));
			default: jmpb = 1'b0;
		endcase
	end
endmodule

