module divider 
#(
    parameter WIDTH=23,
    parameter MODULO=6000000
)
(
    input input_clk,
    output output_clk
);
reg [WIDTH-1:0] counter;
    reg output_clk;
    initial begin
        counter = 0;
        output_clk = 0;
    end
    always @(posedge input_clk) begin
        if (counter == MODULO-1) begin
            counter = 0;
            output_clk = ~output_clk;
        end else begin
            counter = counter + 1;
        end
    end
endmodule

module sep32_cnt(
    input           clk,
    input           cen,
    input           zero,
    output reg [4:0]    cnt
    );
reg last_zero;
    always @(posedge clk) begin
        if (last_zero == 0 && zero == 1) begin
            cnt <= 1;
        end else if (cen == 1) begin
            cnt <= cnt + 1;
        end
        last_zero <= zero;
    end
endmodule

