module jtframe_romrq #(parameter AW=18, DW=8 )(
    input               rst,
    input               clk,
    input               clr, 
    input [21:0]        offset,
    input [AW-1:0]      addr,
    input               addr_ok,    
    input [31:0]        din,
    input               din_ok,
    input               we,
    output reg          req,
    output reg          data_ok,    
    output     [21:0]   sdram_addr,
    output reg [DW-1:0] dout
);
reg [AW-1:0] addr_req;
reg [AW-1:0] cached_addr0, cached_addr1;
reg [DW-1:0] cached_data0, cached_data1;
reg          hit0, hit1;
reg          subaddr;
reg          good;

assign sdram_addr = addr_req + offset;

always @(*) begin
    addr_req = {AW{1'b0}};
    case (DW)
        8: addr_req[7:0] = addr[7:0];
        16: addr_req[15:0] = addr[15:0];
        32: addr_req[31:0] = addr[31:0];
    endcase
end

always @(posedge clk or posedge rst) begin
    if (rst) begin
        hit0 <= 1'b0;
        hit1 <= 1'b0;
        cached_addr0 <= {AW{1'b0}};
        cached_addr1 <= {AW{1'b0}};
        cached_data0 <= {DW{1'b0}};
        cached_data1 <= {DW{1'b0}};
        subaddr <= 1'b0;
        good <= 1'b0;
    end else begin
        if (clr) begin
            hit0 <= 1'b0;
            hit1 <= 1'b0;
            cached_addr0 <= {AW{1'b0}};
            cached_addr1 <= {AW{1'b0}};
            cached_data0 <= {DW{1'b0}};
            cached_data1 <= {DW{1'b0}};
            subaddr <= 1'b0;
            good <= 1'b0;
        end else begin
            if (addr_ok && addr[AW-1:0] == cached_addr0[AW-1:0]) begin
                hit0 <= 1'b1;
                subaddr <= 1'b1;
            end else begin
                hit0 <= 1'b0;
                subaddr <= 1'b0;
            end
            if (addr_ok && addr[AW-1:0] == cached_addr1[AW-1:0]) begin
                hit1 <= 1'b1;
                subaddr <= 1'b1;
            end else begin
                hit1 <= 1'b0;
                subaddr <= 1'b0;
            end
            if (addr_ok && addr[AW-1:0] != cached_addr0[AW-1:0] && addr[AW-1:0] != cached_addr1[AW-1:0]) begin
                cached_addr0 <= addr[AW-1:0];
                cached_data0 <= din;
                cached_addr1 <= addr[AW-1:0];
                cached_data1 <= din;
                good <= 1'b1;
            end else if (we && addr_ok && addr[AW-1:0] == cached_addr0[AW-1:0]) begin
                cached_data0 <= din;
            end else if (we && addr_ok && addr[AW-1:0] == cached_addr1[AW-1:0]) begin
                cached_data1 <= din;
            end
        end
    end
end

always @(posedge clk or posedge rst) begin
    if (rst) begin
        req <= 1'b0;
        data_ok <= 1'b0;
    end else begin
        if (addr_ok && addr[AW-1:0] == cached_addr0[AW-1:0]) begin
            req <= 1'b0;
            data_ok <= 1'b1;
        end else if (addr_ok && addr[AW-1:0] == cached_addr1[AW-1:0]) begin
            req <= 1'b0;
            data_ok <= 1'b1;
        end else if (addr_ok && addr[AW-1:0] != cached_addr0[AW-1:0] && addr[AW-1:0] != cached_addr1[AW-1:0]) begin
            req <= 1'b1;
            data_ok <= 1'b1;
        end else if (we && addr_ok && addr[AW-1:0] == cached_addr0[AW-1:0]) begin
            req <= 1'b0;
            data_ok <= 1'b1;
        end else if (we && addr_ok && addr[AW-1:0] == cached_addr1[AW-1:0]) begin
            req <= 1'b0;
            data_ok <= 1'b1;
        end else if (we && addr_ok && addr[AW-1:0] != cached_addr0[AW-1:0] && addr[AW-1:0] != cached_addr1[AW-1:0]) begin
            req <= 1'b1;
            data_ok <= 1'b1;
        end
    end
end

always @(posedge clk or posedge rst) begin
    if (rst) begin
        dout <= {DW{1'b0}};
    end else begin
        if (we && addr_ok && addr[AW-1:0] == cached_addr0[AW-1:0]) begin
            dout <= cached_data0;
        end else if (we && addr_ok && addr[AW-1:0] == cached_addr1[AW-1:0]) begin
            dout <= cached_data1;
        end else if (we && addr_ok && addr[AW-1:0] != cached_addr0[AW-1:0] && addr[AW-1:0] != cached_addr1[AW-1:0]) begin
            dout <= din;
        end
    end
end

endmodule

