module io_ps2_keyboard(
input wire clk,
input wire kbd_clk,
input wire kbd_dat,
output reg interrupt,
output reg [7:0] scanCode
); 

parameter [31:0] CLK_SPEED=100000000;
parameter timeout_const = CLK_SPEED / 1000000;
parameter debounce_const = CLK_SPEED / 100000;
reg [7:0] shift_reg;  
reg clk_filter;  
reg timeout;  
reg [3:0] bitsCount;  
  always @(posedge clk) begin
    if(timeout == 1'b1) begin
      shift_reg <= {shift_reg[6:0],kbd_dat};
      bitsCount <= bitsCount + 1;
      if(bitsCount == 8) begin
        interrupt <= 1'b1;
        scanCode <= shift_reg;
      end
    end
    else begin
      if(kbd_clk == 1'b1) begin
        clk_filter <= 1'b1;
        timeout <= 1'b0;
      end
      else if(kbd_clk == 1'b0) begin
        if(clk_filter == 1'b1) begin
          clk_filter <= 1'b0;
          timeout <= 1'b1;
          #timeout_const;
          timeout <= 1'b0;
        end
      end
    end
  end
endmodule

