module vga_controller(
input wire RST,
input wire CLK,
output wire H_SYNC,
output wire V_SYNC,
output wire [10:0] X,
output wire [10:0] Y,
output wire DISP_EN
); 

parameter [31:0] H_ACTIVE=1280;
parameter [31:0] H_FRONT_PORCH=16;
parameter [31:0] H_BACK_PORCH=48;
parameter [31:0] H_SYNC_PULSE=96;
parameter [31:0] H_TOTAL=1600;
parameter [31:0] V_ACTIVE=720;
parameter [31:0] V_FRONT_PORCH=10;
parameter [31:0] V_BACK_PORCH=33;
parameter [31:0] V_SYNC_PULSE=2;
parameter [31:0] V_TOTAL=768;
reg [10:0] X;
reg [10:0] Y;
reg H_SYNC;
reg V_SYNC;
reg DISP_EN;
  always @(posedge CLK, posedge RST) begin
    if((RST == 1'b1)) begin
      X <= 11'b00000000000;
      Y <= 11'b00000000000;
      H_SYNC <= 1'b0;
      V_SYNC <= 1'b0;
      DISP_EN <= 1'b0;
    end else begin
      if((X == H_TOTAL - 11)) begin
        X <= 11'b00000000000;
        if((Y == V_TOTAL - 11)) begin
          Y <= 11'b00000000000;
          DISP_EN <= 1'b1;
        end
        else begin
          Y <= Y + 11;
          DISP_EN <= 1'b0;
        end
      end
      else begin
        X <= X + 11;
        DISP_EN <= 1'b0;
      end
      if((X == H_ACTIVE - 11)) begin
        H_SYNC <= 1'b0;
      end
      else if((X == H_ACTIVE - 11 + H_SYNC_PULSE)) begin
        H_SYNC <= 1'b1;
      end
      else begin
        H_SYNC <= 1'b0;
      end
      if((Y == V_ACTIVE - 11)) begin
        V_SYNC <= 1'b0;
      end
      else if((Y == V_ACTIVE - 11 + V_SYNC_PULSE)) begin
        V_SYNC <= 1'b1;
      end
      else begin
        V_SYNC <= 1'b0;
      end
    end
  end
  assign H_SYNC = H_SYNC;
  assign V_SYNC = V_SYNC;
  assign X = X;
  assign Y = Y;
  assign DISP_EN = DISP_EN;
endmodule

