module tx_add_preamble(
input wire clk,
input wire data_valid_in,
input wire [7:0] data_in,
output reg data_valid_out,
output reg [7:0] data_out
); 

reg [63:0] delay_data;
reg [7:0] delay_data_valid;
  always @(posedge clk) begin
    delay_data <= {delay_data[62:0],data_in};
    delay_data_valid <= {delay_data_valid[6:0],data_valid_in};
  end
  always @(posedge clk) begin
    if((delay_data_valid[7] == 1'b1)) begin
      data_out <= delay_data[7:0];
      data_valid_out <= 1'b1;
    end
    else if((delay_data_valid[6] == 1'b1)) begin
      data_out <= 8'b11010101;
      data_valid_out <= 1'b1;
    end
    else if((data_valid_in == 1'b1)) begin
      data_out <= 8'b01010101;
      data_valid_out <= 1'b1;
    end
    else begin
      data_out <= 8'b00000000;
      data_valid_out <= 1'b0;
    end
  end
endmodule

