module ps2controller (
    input reset,
    input i_clock,
    input i_data,
    output scan_ready,
    output [7:0] scan_code
);
reg [7:0] scan_code;
    reg [3:0] counter;
    wire ready;
    assign scan_ready = ready;
    assign scan_code = scan_code;
    always @(negedge i_clock) begin
        if (reset) begin
            scan_code <= 8'b0;
            counter <= 4'b0;
        end else begin
            if (counter == 4'b1111) begin
                scan_code <= {i_data, scan_code[7:1]};
                counter <= 4'b0;
            end else begin
                scan_code[counter] <= i_data;
                counter <= counter + 1'b1;
            end
        end
    end
    always @(negedge i_clock) begin
        if (reset) begin
            ready <= 1'b0;
        end else begin
            ready <= (counter == 4'b1111 && scan_code[9] == 1'b0);
        end
    end
endmodule

