module dhcp_client_m_axis_open_port_fifo
#(parameter
    DATA_BITS  = 8,
    DEPTH_BITS = 4
)(
    input  wire                 clk,
    input  wire                 aclr,
    output wire                 empty_n,
    output wire                 full_n,
    input  wire                 read,
    input  wire                 write,
    output wire [DATA_BITS-1:0] dout,
    input  wire [DATA_BITS-1:0] din
);
localparam
    DEPTH = 1 << DEPTH_BITS;

reg  [DEPTH_BITS-1:0]  index;
reg  [DATA_BITS-1:0]  mem [0:DEPTH-1];
wire [DATA_BITS-1:0]  dout_tmp;

assign empty_n = (index == 0);
assign full_n  = (index == DEPTH-1);
assign dout    = dout_tmp;

always @(posedge clk or posedge aclr) begin
    if (aclr) begin
        index <= 0;
    end else if (write && !read) begin
        index <= index + 1;
    end
end

always @(posedge clk or posedge aclr) begin
    if (aclr) begin
        mem[0] <= 0;
    end else if (write && !read) begin
        mem[index] <= din;
    end
end

always @(posedge clk or posedge aclr) begin
    if (aclr) begin
        dout_tmp <= 0;
    end else if (read) begin
        dout_tmp <= mem[index - 1];
    end
end

endmodule

