module synchronize(
    input clk,
    input async_in,
    input reset,
    output reg sync_out
    );
reg sync_out_d;
    reg sync_out_q;
    always @(posedge clk or posedge reset)
    begin
        if (reset)
        begin
            sync_out_d <= 0;
            sync_out_q <= 0;
        end
        else
        begin
            sync_out_d <= async_in;
            sync_out_q <= sync_out_d;
        end
    end
    always @(posedge clk or posedge reset)
    begin
