module udpLoopback_lbRxMetadataIn_reg_slice
#(parameter
    N = 8   
) (

    input  wire         clk,
    input  wire         reset,

    input  wire [N-1:0] s_data,
    input  wire         s_valid,
    output wire         s_ready,

    output wire [N-1:0] m_data,
    output wire         m_valid,
    input  wire         m_ready
);
localparam [1:0]
    ZERO = 2'b10,
    ONE  = 2'b11,
    TWO  = 2'b01;

reg  [N-1:0] data_p1;
reg  [N-1:0] data_p2;
wire         load_p1;
wire         load_p2;
wire         load_p1_from_p2;
reg          state;
wire         s_ready_t;
wire         load_p1_from_s;
wire         m_valid_t;
wire         load_p2_from_s;

assign s_ready = s_ready_t;
assign m_data  = data_p1;
assign m_valid = m_valid_t;

always @(posedge clk) begin
    if (reset) begin
        data_p1 <= {N{1'b0}};
        data_p2 <= {N{1'b0}};
        state   <= ZERO;
    end else begin
        if (load_p1_from_p2) begin
            data_p1 <= data_p2;
            state   <= state;
        end else if (load_p1_from_s) begin
            data_p1 <= {N{1'b0}};
            state   <= ONE;
        end else if (load_p2_from_s) begin
            data_p2 <= s_data;
            state   <= TWO;
        end else begin
            state <= state;
        end
    end
end


assign load_p1 = (state == ZERO && s_valid) ||
                  (state == ONE && m_ready) ||
                  (state == TWO && s_valid);
assign load_p2 = (state == ONE && m_ready) ||
                  (state == TWO && s_valid) ||
                  (state == ZERO && s_valid);
assign load_p1_from_p2 = (state == TWO && s_valid);
assign load_p1_from_s  = (state == ZERO && s_valid);
assign load_p2_from_s  = (state == ONE && m_ready);

assign s_ready_t = (state == ZERO) || (state == ONE && m_ready);
assign m_valid_t = (state == TWO) && s_valid;

endmodule

