            6'b000001: BSout = 4'b0000;
            6'b000010: BSout = 4'b0001;
            6'b000011: BSout = 4'b0010;
            6'b000100: BSout = 4'b0011;
            6'b000101: BSout = 4'b0100;
            6'b000110: BSout = 4'b0101;
            6'b000111: BSout = 4'b0110;
            6'b001000: BSout = 4'b0111;
            6'b001001: BSout = 4'b1000;
            6'b001010: BSout = 4'b1001;
            6'b001011: BSout = 4'b1010;
            6'b001100: BSout = 4'b1011;
            6'b001101: BSout = 4'b1100;
            6'b001110: BSout = 4'b1101;
            6'b001111: BSout = 4'b1110;
            6'b010000: BSout = 4'b1111;
            default: BSout = 4'b0000;
        endcase
    end
