module voltage_test01(
input wire pi_base_clk,
input wire [9:0] pi_sw,
input wire [3:0] pi_btn_n,
output wire [9:0] po_led_r,
output wire [7:0] po_led_g,
output wire [3:0] po_gpio0,
output wire [9:0] po_gpio1
); 

parameter [31:0] FREQ_DEVIDE=1000000;
reg reg_btn_flg = 1'b0;
reg reg_key3_cnt = 1'b0;
wire wr_rst_n = pi_btn_n[0];
  always @(posedge wr_rst_n, posedge pi_base_clk) begin
    if(wr_rst_n == 1'b0) begin
      reg_btn_flg <= 1'b0;
    end else begin
      reg_btn_flg <= reg_btn_flg + 1;
    end
  end
  always @(posedge wr_rst_n, posedge pi_base_clk) begin
    if(wr_rst_n == 1'b0) begin
      reg_key3_cnt <= 1'b0;
    end else begin
      if((pi_btn_n[3] == 1'b0 && reg_btn_flg == 1'b0)) begin
        reg_key3_cnt <= reg_key3_cnt + 1;
      end
    end
  end
  assign po_led_r = reg_key3_cnt;
  assign po_led_g = pi_sw;
  assign po_gpio0 = pi_sw;
  assign po_gpio1 = pi_sw;
endmodule

module pdmout
    #(parameter RESOLUTION = 16) (
        input wire clk,         
        input wire enable,
        input wire [RESOLUTION-1:0] value,
        output wire pdm,
        output wire en
    );
reg [RESOLUTION:0] PWM_accumulator;
    assign en = enable;
    assign pdm = PWM_accumulator[RESOLUTION];
    always @(posedge clk) begin
        if (enable) begin
            PWM_accumulator <= PWM_accumulator + value;
        end else begin
            PWM_accumulator <= 0;
        end
    end
endmodule

