                4'h5: sseg <= 8'b10110110;
                4'h6: sseg <= 8'b10111110;
                4'h7: sseg <= 8'b11100000;
                4'h8: sseg <= 8'b11111110;
                4'h9: sseg <= 8'b11110110;
                4'ha: sseg <= 8'b11101110;
                4'hb: sseg <= 8'b00111110;
                4'hc: sseg <= 8'b10011100;
                4'hd: sseg <= 8'b01111010;
                4'he: sseg <= 8'b10011110;
                4'hf: sseg <= 8'b10001110;
            endcase
            sseg[7] <= dp[1];
        end
    end
    always @(posedge clk or posedge reset) begin
        if(reset) sseg <= 0;
        else begin
            case(hex1)
                4'h0: sseg <= 8'b11111100;
                4'h1: sseg <= 8'b01100000;
                4'h2: sseg <= 8'b11011010;
                4'h3: sseg <= 8'b11110010;
                4'h4: sseg <= 8'b01100110;
                4'h5: sseg <= 8'b10110110;
                4'h6: sseg <= 8'b10111110;
                4'h7: sseg <= 8'b11100000;
                4'h8: sseg <= 8'b11111110;
                4'h9: sseg <= 8'b11110110;
                4'ha: sseg <= 8'b11101110;
                4'hb: sseg <= 8'b00111110;
                4'hc: sseg <= 8'b10011100;
                4'hd: sseg <= 8'b01111010;
                4'he: sseg <= 8'b10011110;
                4'hf: sseg <= 8'b10001110;
            endcase
            sseg[7] <= dp[2];
        end
    end
    always @(posedge clk or posedge reset) begin
        if(reset) sseg <= 0;
        else begin
            case(hex0)
                4'h0: sseg <= 8'b11111100;
                4'h1: sseg <= 8'b01100000;
                4'h2: sseg <= 8'b11011010;
                4'h3: sseg <= 8'b11110010;
