module Divider #(parameter Time=20)
(
    input I_CLK,
    output reg O_CLK
);
reg [31:0] counter = 0;
    initial begin
        O_CLK = 0;
    end
    always @(posedge I_CLK) begin
        if (counter == Time/2) begin
            counter = 0;
            O_CLK = ~O_CLK;
        end
        else begin
            counter = counter + 1;
        end
    end
endmodule

