module stratixiii_bias_logic (
    clk,
    shiftnld,
    captnupdt,
    mainclk,
    updateclk,
    capture,
    update
    );


input  clk;
input  shiftnld;
input  captnupdt;


output mainclk;
output updateclk;
output capture;
output update;
reg mainclk_tmp;
reg updateclk_tmp;
reg capture_tmp;
reg update_tmp;

always @ (captnupdt or shiftnld or clk)
    begin
        case ({captnupdt, shiftnld})
            2'b10: begin
                mainclk_tmp = 1'b0;
                updateclk_tmp = 1'b0;
                capture_tmp = 1'b1;
                update_tmp = 1'b0;
            end
            2'b11: begin
                mainclk_tmp = 1'b0;
                updateclk_tmp = 1'b0;
                capture_tmp = 1'b1;
                update_tmp = 1'b1;
            end
            2'b01: begin
                mainclk_tmp = 1'b0;
                updateclk_tmp = 1'b0;
                capture_tmp = 1'b0;
                update_tmp = 1'b0;
            end
            2'b00: begin
                mainclk_tmp = 1'b1;
                updateclk_tmp = 1'b0;
                capture_tmp = 1'b0;
                update_tmp = 1'b0;
            end
            default: begin
                mainclk_tmp = 1'b0;
                updateclk_tmp = 1'b0;
                capture_tmp = 1'b0;
                update_tmp = 1'b0;
            end
        endcase
    end

and (mainclk, mainclk_tmp, 1'b1);
and (updateclk, updateclk_tmp, 1'b1);
and (capture, capture_tmp, 1'b1);
and (update, update_tmp, 1'b1);

initial
    begin
        mainclk_tmp = 1'b0;
        updateclk_tmp = 1'b0;
        capture_tmp = 1'b0;
        update_tmp = 1'b0;
    end

endmodule

module syn_gen
(
    input              I_pxl_clk   ,
    input              I_rst_n     ,
    input      [15:0]  I_h_total   ,
    input      [15:0]  I_h_sync    ,
    input      [15:0]  I_h_bporch  ,
    input      [15:0]  I_h_res     ,
    input      [15:0]  I_v_total   ,
    input      [15:0]  I_v_sync    ,
    input      [15:0]  I_v_bporch  ,
    input      [15:0]  I_v_res     ,
    input      [15:0]  I_rd_hres   ,
    input      [15:0]  I_rd_vres   ,
    input              I_hs_pol    ,
    input              I_vs_pol    ,
    output reg         O_rden      ,
    output reg         O_de        ,   
    output reg         O_hs        ,
    output reg         O_vs         
);
reg [15:0] V_cnt;
    reg [15:0] H_cnt;
    reg Pout_de_w;
    reg Pout_hs_w;
    reg Pout_vs_w;
    reg Rden_w;
    always @(posedge I_pxl_clk or negedge I_rst_n) begin
        if (!I_rst_n) begin
            V_cnt <= 0;
            H_cnt <= 0;
        end else begin
            if (V_cnt == I_v_total) begin
                V_cnt <= 0;
                H_cnt <= H_cnt + 1;
            end else begin
                V_cnt <= V_cnt + 1;
            end
        end
    end
    always @(posedge I_pxl_clk or negedge I_rst_n) begin
        if (!I_rst_n) begin
            Pout_de_w <= 0;
            Pout_hs_w <= 0;
            Pout_vs_w <= 0;
            Rden_w <= 0;
        end else begin
            Pout_de_w <= (H_cnt < I_h_res) && (V_cnt < I_v_res);
            Pout_hs_w <= (H_cnt < I_h_res) && (V_cnt < I_v_res) && (H_cnt >= I_h_sync) && (H_cnt < (I_h_sync + I_h_bporch));
            Pout_vs_w <= (H_cnt < I_h_res) && (V_cnt < I_v_res) && (V_cnt >= I_v_sync) && (V_cnt < (I_v_sync + I_v_bporch));
            Rden_w <= (H_cnt < I_h_res) && (V_cnt < I_v_res);
        end
    end
    always @(posedge I_pxl_clk or negedge I_rst_n) begin
        if (!I_rst_n) begin
            O_de <= 0;
            O_hs <= 0;
            O_vs <= 0;
            O_rden <= 0;
        end else begin
            O_de <= Pout_de_w;
            O_hs <= Pout_hs_w;
            O_vs <= Pout_vs_w;
            O_rden <= Rden_w;
        end
    end
    assign O_de = I_hs_pol ? ~O_de : O_de;
    assign O_hs = I_hs_pol ? ~O_hs : O_hs;
    assign O_vs = I_vs_pol ? ~O_vs : O_vs;
endmodule

