module alu
    #(parameter WIDTH = 32)
    (   input  [WIDTH - 1 : 0] a,b,
        input  [2 : 0] m,
        output reg [WIDTH - 1 : 0] y,
        output reg zf,      
        output reg cf,      
        output reg of      
    );
always @* begin
        case (m)
            3'b000: y = a + b; cf = y[WIDTH - 1]; of = a[WIDTH - 1] ^ b[WIDTH - 1] ^ y[WIDTH - 1];
            3'b001: y = a - b; cf = y[WIDTH - 1]; of = a[WIDTH - 1] ^ b[WIDTH - 1] ^ y[WIDTH - 1];
            3'b010: y = a & b; of = 0;
            3'b011: y = a | b; of = 0;
            3'b100: y = a ^ b; of = 0;
            3'b101: y = a; of = 0;
            3'b110: y = b; of = 0;
            3'b111: y = 0; of = 0;
        endcase
    end
    always @* begin
        zf = (y == 0);
    end
endmodule

