module pddm (
	input sdi, 
	input signed_data, 
	output [31:0] dout, 
	input ock, uck, 
	input rstn, clk
);
reg [31:0] sigma;
	reg [31:0] undersampled_sigma;
	reg [31:0] delta;
	reg [31:0] deriv;

	always @(posedge clk or negedge rstn) begin
		if (!rstn) begin
			sigma <= 0;
			undersampled_sigma <= 0;
			delta <= 0;
			deriv <= 0;
		end else begin
			if (ock) begin
				if (sdi) begin
					sigma <= sigma + 1;
				end else begin
					sigma <= sigma - 1;
				end
			end
			if (uck) begin
				if (sdi) begin
					undersampled_sigma <= undersampled_sigma + 1;
				end else begin
					undersampled_sigma <= undersampled_sigma - 1;
				end
			end
			if (sdi) begin
				delta <= undersampled_sigma - sigma;
			end else begin
				delta <= sigma - undersampled_sigma;
			end
			if (signed_data) begin
				deriv <= delta;
			end else begin
				deriv <= delta - 1;
			end
		end
	end

	assign dout = signed_data ? {deriv[31], deriv[30:0]} : {deriv[31], deriv[30:0]};

endmodule

module RegFile(
    output reg signed  [31:0] ReadData1, ReadData2,
    input [4:0] ReadReg1, ReadReg2, WriteReg,
    input signed [31:0] WriteData,
    input RegWrite, Clk
    );
reg signed [31:0] RegFile [31:0];
    always @(negedge Clk)
    begin
        if (ReadReg1 != 0)
            ReadData1 <= RegFile[ReadReg1];
        else
            ReadData1 <= 0;
        if (ReadReg2 != 0)
            ReadData2 <= RegFile[ReadReg2];
        else
            ReadData2 <= 0;
    end
    always @(posedge Clk)
    begin
        if (RegWrite)
            RegFile[WriteReg] <= WriteData;
    end
endmodule

