					output Clk_CPU,
					output reg readn
					);
reg[31:0]counter;
	reg[31:0]step;
	reg auto_clk;
	reg wasReady;

	always @(posedge clk or posedge rst)
	begin
		if(rst)
		begin
			counter <= 0;
			step <= 0;
			auto_clk <= 0;
			wasReady <= 0;
			readn <= 0;
		end
		else
		begin
			if(keyReady)
			begin
				if(BTN_OK[0])
				begin
					counter <= 0;
					step <= 0;
					auto_clk <= 0;
					wasReady <= 1;
					readn <= 1;
				end
				else if(BTN_OK[1])
				begin
					counter <= 0;
					step <= 0;
					auto_clk <= 0;
					wasReady <= 1;
