module timer_stream_adapter_synchTime_2_fifo
#(parameter
    DATA_BITS  = 8,
    DEPTH_BITS = 4
)(
    input  wire                 clk,
    input  wire                 aclr,
    output wire                 empty_n,
    output wire                 full_n,
    input  wire                 read,
    input  wire                 write,
    output wire [DATA_BITS-1:0] dout,
    input  wire [DATA_BITS-1:0] din
);
localparam DEPTH = 1 << DEPTH_BITS;

reg [DEPTH_BITS-1:0] index;
reg [DEPTH-1:0]      mem [0:DEPTH-1];
reg                  empty;
reg                  full;

assign empty_n = ~empty;
assign full_n  = ~full;
assign dout    = mem[index];

always @(posedge clk or posedge aclr) begin
    if (aclr) begin
        index <= 0;
        empty <= 1;
        full  <= 0;
    end else begin
        if (write && !full) begin
            mem[index] <= din;
            index <= index + 1;
            empty <= 0;
            full  <= 1;
        end
        if (read && !empty) begin
            index <= index - 1;
            empty <= 1;
            full  <= 0;
        end
    end
end

endmodule

module debounce(
input clk,
input btn_input,
output reg btn_output
);
reg [31:0] timer;
reg pre;
always @(posedge clk) begin
    if (timer == 32'd1000000) begin
        if (btn_input == pre) begin
            btn_output <= btn_input;
        end
        timer <= 0;
        pre <= btn_input;
    end
    else begin
        timer <= timer + 1;
    end
end
endmodule

