module gray_Nbits (clk, reset, enable, gray_out);

input wire clk, reset, enable;
output wire [N-1:0]gray_out;
parameter N = 4;
parameter SIZE = N+1;
reg [SIZE-1:0]state = Zeros;
reg [SIZE-1:0]toggle = Zeros;
reg [SIZE-1:0]gray_out = Zeros;

assign gray_out = state[SIZE-2:0];

always @(posedge clk or posedge reset)
begin
	if (reset)
		state <= Zeros;
	else if (enable)
		state <= {toggle[0], state[SIZE-2:1] ^ state[SIZE-1:2]};
end

always @(state)
begin
	toggle[0] = 1;
	for (int i = 1; i < SIZE; i = i + 1)
		toggle[i] = (state[i-1] ^ state[i-2]) & (state[i-1] ^ state[i-3]) | (state[i-1] ^ state[i-2] ^ state[i-3]);
end

endmodule

