reg [DATA_WIDTH-1:0] mem [2**ADDR_WIDTH-1:0];
reg [DATA_WIDTH-1:0] mem_bypass [2**ADDR_WIDTH-1:0];



initial begin
    if (CLEAR_ON_INIT) begin
        mem = 0;
        mem_bypass = 0;
    end
end

always @(posedge clk) begin
    if (ENABLE_BYPASS) begin
        mem_bypass[waddr] <= din;
    end else begin
        mem[waddr] <= din;
    end
end

always @(posedge clk) begin
    if (ENABLE_BYPASS) begin
        dout <= mem_bypass[raddr];
    end else begin
        dout <= mem[raddr];
    end
end

endmodule

