module data_deal(
	clk,
	rst_n,
	data_in,
	data_in_sign,

	data_out,
	data_out_sign,
	data_valid,
	data_ok
    );



	input 	clk;
	input 	rst_n;
	input 	[6:0]	data_in;
	input 	data_in_sign;

	output	[6:0]	data_out;
	output	data_out_sign;
	input 	data_valid;
	output	data_ok;
reg	[6:0]	data_reg;
	reg	data_regnum;
	reg	data_out_sign;
	reg	data_out;

	always @(negedge rst_n or posedge clk) begin
		if (rst_n == 1'b0) begin
			data_reg <= 7'b0;
			data_regnum <= 1'b0;
			data_out_sign <= 1'b0;
			data_out <= 7'b0;
		end else begin
			if (data_in_sign == 1'b1) begin
				data_reg <= data_reg + data_in;
				data_regnum <= data_regnum + 1'b1;
			end
			if (data_valid == 1'b1) begin
				data_out_sign <= 1'b1;
				data_out <= data_out + 1'b1;
			end
			if (data_regnum == 8'b10000000) begin
				if (data_reg == 7'b14) begin
					data_ok <= 1'b1;
				end else if (data_reg == 7'b20) begin
					data_ok <= 1'b1;
				end else begin
					data_ok <= 1'b0;
				end
			end
		end
	end
endmodule

module clk_div(
input wire clk_100MHz,
input wire reset,
output wire clk_100Hz
); 

reg [31:0] ticks = 499999;
reg clk_out = 1'b0;
  always @(posedge clk_100MHz, posedge reset) begin
    if(reset == 1'b1) begin
      ticks <= 499999;
      clk_out <= 1'b0;
    end else begin
      ticks <= ticks - 1;
      if(ticks == 0) begin
        clk_out <=  ~clk_out;
      end
    end
  end
  assign clk_100Hz = clk_out;
endmodule

