module DelayLoop(MR,Timeout,Clock) ;
input			MR, Clock;
output reg	Timeout;
parameter Divider = 100000;
reg [26:0] counter;
always @(posedge Clock) begin
	if (MR) begin
		counter <= 0;
		Timeout <= 0;
	end else if (counter == Divider) begin
		Timeout <= 1;
	end else begin
		Timeout <= 0;
	end
end
always @(posedge Clock) begin
	if (MR) begin
		counter <= 0;
	end else begin
		counter <= counter + 1;
	end
end
endmodule

