    if((clr == 1'b1)) begin
      cnt <= {16{1'b0}};
    end else begin
      if((cnten == 1'b1)) begin
        if((cnt == 16'b1111111111111111)) begin
          cnt <= {16{1'b0}};
        end
        else begin
          cnt <= cnt + 1;
        end
      end
    end
  end
  assign q = cnt;
endmodule

