input [DATA_WIDTH-1:0]din;
output [DATA_WIDTH-1:0]dout;
parameter ADD_STATE = 1'b0;
parameter INC_STATE = 1'b1;

reg [DATA_WIDTH-1:0]counter;
reg state;

always @(posedge clk or negedge arstn)
begin
    if(!arstn)
    begin
        counter <= 0;
        state <= ADD_STATE;
    end
    else
    begin
        case(state)
            ADD_STATE: begin
                if(mode)
                    counter <= din + 1;
                else
                    counter <= din + 2;
                if(mode)
                    state <= INC_STATE;
                else
                    state <= ADD_STATE;
            end
            INC_STATE: begin
                if(mode)
                    state <= ADD_STATE;
                else
                    counter <= counter + 1;
            end
        endcase
    end
end

assign dout = counter;

endmodule

