generate
    for (i=0; i<DEPTH; i=i+1) begin : shiftreg
        reg s_empty_n, s_full_n;
        wire s_read, s_write;
        wire [DATA_BITS-1:0] s_din, s_dout;
        assign s_read = (i == 0);
        assign s_write = (i == DEPTH-1);
        assign s_din = (i == index) ? din : mem[i-1];
        assign s_dout = mem[i];
        udpAppMux_txLengthNetwork_fifo
        #(
            .DATA_BITS(DATA_BITS),
            .DEPTH_BITS(DEPTH_BITS)
        )
        u_udpAppMux_txLengthNetwork_fifo
        (
