module Counter_Controller #(
    parameter   DWIDTH = 7
)(
    input                   clk,
    input                   rst_n,
    input                   start_i,
    input   [DWIDTH-1:0]    cnt_val_i,
    input   [DWIDTH-1:0]    cnt_i,
    output                  run_o,
    output                  done_o
);
localparam   S_IDLE = 0;
    localparam   S_RUN = 1;
    localparam   S_DONE = 2;

    reg [1:0] state;
    reg [DWIDTH-1:0] cnt_val;
    reg [DWIDTH-1:0] cnt_val_n;
    reg run;
    reg done;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= S_IDLE;
            cnt_val <= 0;
            run <= 0;
            done <= 0;
        end
        else begin
            state <= state_n;
            cnt_val <= cnt_val_n;
            run <= run_o;
            done <= done_o;
        end
    end

    always @(*) begin
        state_n = state;
        cnt_val_n = cnt_val;
        run_o = 0;
        done_o = 0;
        case (state)
            S_IDLE: begin
                if (start_i) begin
                    state_n = S_RUN;
                    cnt_val_n = cnt_val_i;
                    run_o = 1;
                end
            end
            S_RUN: begin
                if (cnt_val == cnt_i) begin
                    state_n = S_DONE;
                    done_o = 1;
                end
                else begin
                    run_o = 1;
                end
            end
            S_DONE: begin
                state_n = S_IDLE;
                run_o = 0;
            end
        endcase
    end

endmodule

