module sparc_ifu_esl_lfsr
(
    input               clk,
    input               rst_n,


    input [15:0]        lfsr_seed,
    input               lfsr_ld,


    input               lfsr_step,


    output reg [15:0]   lfsr_state_f,


    output reg          lfsr_out_f
);
localparam LFSR_WIDTH = 16;
    localparam LFSR_FEEDBACK_TAPS = 16'b00000000000000000000000000000001;

    reg [LFSR_WIDTH-1:0] lfsr_state_n;


    always @(posedge clk or negedge rst_n)
    begin
        if (!rst_n)
        begin
            lfsr_state_n <= {LFSR_WIDTH{1'b0}};
        end
        else
        begin
            if (lfsr_ld)
            begin
                lfsr_state_n <= lfsr_seed;
            end
            else if (lfsr_step)
            begin
                lfsr_state_n <= lfsr_state_f;
            end
            else
            begin
                lfsr_state_n <= {lfsr_state_f[LFSR_WIDTH-2:0], lfsr_state_f[LFSR_WIDTH-1] ^ lfsr_state_f[LFSR_WIDTH-2] ^ lfsr_state_f[LFSR_WIDTH-3] ^ lfsr_state_f[LFSR_WIDTH-4]};
            end
        end
    end


    always @(lfsr_state_n)
    begin
        lfsr_out_f <= lfsr_state_n[LFSR_WIDTH-1];
    end


    always @(lfsr_state_n)
    begin
        lfsr_state_f <= lfsr_state_n;
    end

endmodule

module mux4_1n (
