    wire [1:0] S;
    assign S = {A, B};
    always @ (EN_n or D0 or D1 or D2 or D3 or A or B) begin
        if (EN_n == 1'b0) begin
            Y_reg <= 1'b0;
        end else begin
            case (S)
                2'b00: Y_reg <= D0;
                2'b01: Y_reg <= D1;
                2'b10: Y_reg <= D2;
                2'b11: Y_reg <= D3;
            endcase
        end
    end
    assign Y = Y_reg;
endmodule

