module echo_server_application_m_axis_read_package_reg_slice
#(parameter
    N = 8   
) (

    input  wire         clk,
    input  wire         reset,

    input  wire [N-1:0] s_data,
    input  wire         s_valid,
    output wire         s_ready,

    output wire [N-1:0] m_data,
    output wire         m_valid,
    input  wire         m_ready
);
localparam [1:0]
    ZERO = 2'b10,
    ONE  = 2'b11,
    TWO  = 2'b01;

reg  [N-1:0] data_p1;
reg  [N-1:0] data_p2;
wire         load_p1 = s_valid & s_ready;
wire         load_p2 = m_ready & m_valid;
reg          load_p1_from_p2;
reg  [1:0]   state;
reg  [1:0]   next;
wire         s_ready_t;
wire         s_data_valid;
wire         s_valid_int;
wire         s_ready_int;
wire         m_valid_int;
wire [N-1:0] m_data_int;

assign s_data_valid = s_valid & s_ready;
assign s_ready_t = (state == ZERO) ? 1'b1 : 1'b0;
assign s_valid_int = s_valid & s_ready & ~m_valid;
assign s_ready_int = (state == ZERO) ? 1'b1 : 1'b0;
assign m_valid_int = m_ready & m_valid;
assign m_data_int = data_p1;

always @(posedge clk) begin
    if (reset) begin
        data_p1 <= {N{1'b0}};
        data_p2 <= {N{1'b0}};
        load_p1_from_p2 <= 1'b0;
        state <= ZERO;
    end else begin
        data_p1 <= data_p2;
        data_p2 <= {N{1'b0}};
        load_p1_from_p2 <= 1'b0;
        state <= next;
        if (load_p1) begin
            data_p1 <= s_data;
        end
        if (load_p2) begin
            data_p2 <= m_data_int;
            load_p1_from_p2 <= 1'b1;
        end
    end
end


always @(posedge clk) begin
    if (reset) begin
        next <= ZERO;
    end else begin
        next <= state;
        case (state)
            ZERO: begin
                if (s_data_valid & ~s_valid_int) begin
                    next <= ONE;
                end
            end
            ONE: begin
                if (~s_data_valid & m_valid_int) begin
                    next <= TWO;
                end
                else if (~s_valid_int & m_valid_int) begin
                    next <= ONE;
                end
            end
            TWO: begin
                if (s_data_valid & ~s_valid_int) begin
                    next <= ZERO;
                end
            end
            default: begin
            end
        endcase
    end
end


assign m_valid = (state == ONE) ? 1'b1 : 1'b0;
assign m_data = (state == ONE) ? s_data : {N{1'b0}};
assign s_ready = s_ready_t;
assign m_data = data_p1;

endmodule

