module SynFifo #
(
    parameter DATA_WIDTH = 8,
    parameter FIFO_DEPTH = 256
)
(clk,arstn,data_in,wrreq,rdreq,data_out,usedw,empty,full);

input clk;
input arstn;
input [DATA_WIDTH-1:0]data_in;
input wrreq;
input rdreq;
output [DATA_WIDTH-1:0]data_out;
output reg [clog2_FIFO_DEPTH:0]usedw;
output empty;
output full;
parameter clog2_FIFO_DEPTH = $clog2(FIFO_DEPTH);

reg [clog2_FIFO_DEPTH-1:0]wrptr;
reg [clog2_FIFO_DEPTH-1:0]rptr;

reg [DATA_WIDTH-1:0]mem [0:FIFO_DEPTH-1];

always @(posedge clk or negedge arstn)
begin
    if(!arstn)
    begin
        wrptr <= 0;
        rptr <= 0;
    end
    else
    begin
        if(wrreq)
        begin
            if(wrptr == FIFO_DEPTH-1)
                wrptr <= 0;
            else
                wrptr <= wrptr + 1;
        end
        if(rdreq)
        begin
            if(rptr == FIFO_DEPTH-1)
                rptr <= 0;
            else
                rptr <= rptr + 1;
        end
    end
end

always @(posedge clk or negedge arstn)
begin
    if(!arstn)
        usedw <= 0;
    else
        usedw <= wrptr - rptr;
end

assign empty = (wrptr == rptr);
assign full = (wrptr == rptr+1);

assign data_out = mem[rptr];

always @(wrptr or rptr)
begin
    if(wrptr == rptr)
        mem[wrptr] <= data_in;
    else
        mem[wrptr] <= mem[rptr];
end

endmodule

