module Data_CrossDomain(
    input clkA,
    input FlagIn_clkA, 
    input clkB,
    output FlagOut_clkB,
	input [7:0] dataA,
	output [7:0] dataB
);
reg FlagToggle_clkA;
    reg [2:0] SyncA_clkB;
    reg clkA_data;
    reg clkB_data;
    always @(posedge clkA) begin
        FlagToggle_clkA <= FlagIn_clkA;
        if (FlagToggle_clkA == 1'b1) begin
            clkA_data <= dataA;
        end
    end
    always @(posedge clkB) begin
        if (SyncA_clkB[2:0] == 3'b000) begin
            clkB_data <= clkA_data;
        end
        SyncA_clkB <= {SyncA_clkB[1:0], clkA_data};
        FlagOut_clkB <= SyncA_clkB[2];
    end
endmodule

module gh_delay_programmable_31(
input wire CLK,
input wire rst,
input wire srst,
input wire D,
input wire [4:0] DELAY,
output wire Q
); 

wire [4:0] D_d1;
wire [4:0] D_d2;
wire [4:0] D_d4;
wire [4:0] D_d8;
wire [4:0] D_d16;
wire [4:0] Q_d1;
wire [4:0] Q_d2;
wire [4:0] Q_d4;
wire [4:0] Q_d8;
wire [4:0] Q_d16;
  gh_delay #(
      .DELAY(2))
  gh_delay_0(
      .CLK(CLK),
    .rst(rst),
    .srst(srst),
    .D(D),
    .Q(Q_d1));
  gh_delay #(
      .DELAY(4))
  gh_delay_1(
      .CLK(CLK),
    .rst(rst),
    .srst(srst),
    .D(Q_d1),
    .Q(Q_d2));
  gh_delay #(
      .DELAY(8))
  gh_delay_2(
      .CLK(CLK),
    .rst(rst),
    .srst(srst),
    .D(Q_d2),
    .Q(Q_d4));
  gh_delay #(
      .DELAY(16))
  gh_delay_3(
      .CLK(CLK),
    .rst(rst),
    .srst(srst),
    .D(Q_d4),
    .Q(Q_d8));
  gh_delay #(
      .DELAY(31))
  gh_delay_4(
      .CLK(CLK),
    .rst(rst),
    .srst(srst),
    .D(Q_d8),
    .Q(Q_d16));
  assign D_d1 = D;
  assign D_d2 = Q_d1;
  assign D_d4 = Q_d2;
  assign D_d8 = Q_d4;
  assign D_d16 = Q_d8;
  assign Q = DELAY == 5'b00000 ? D : DELAY == 5'b00001 ? D_d1 : DELAY == 5'b00010 ? D_d2 : DELAY == 5'b00011 ? D_d4 : DELAY == 5'b00100 ? D_d8 : DELAY == 5'b00101 ? D_d16 : 1'b0;
endmodule

module mulor_3_stage_signed_10_bit(
	input signed [9:0] a,
	input signed [9:0] b,
	input signed [9:0] c,
	output [9:0] out,
	input clk);
logic signed [19:0] stage0;
	logic signed [19:0] stage1;
	logic signed [19:0] stage2;

	always @(posedge clk) begin
	stage0 <= (a * b) | c;
	stage1 <= stage0;
	stage2 <= stage1;
	end

	assign out = stage2;
endmodule

