module testbench;
reg [2:0] A, B;
    wire A_greater, A_equal, A_less;
    integer i, error;

    comparator_3bit comparator(A, B, A_greater, A_equal, A_less);

    initial begin
        for (i = 0; i < 100; i = i + 1) begin
            A = $random;
            B = $random;
            if (A_greater != (A > B)) begin
                $display("Test failed at %d", i);
                error = error + 1;
            end
            if (A_equal != (A == B)) begin
                $display("Test failed at %d", i);
                error = error + 1;
            end
            if (A_less != (A < B)) begin
                $display("Test failed at %d", i);
                error = error + 1;
            end
        end
        if (error == 0) begin
            $display("Design passed");
        end
        else begin
            $display("Design failed with %d errors", error);
        end
    end
endmodule

