  v_i,
  enq_not_deq_i,
  full_o,
  empty_o,
  data_o
);
input [61:0] data_i;
output [61:0] data_o;
input clk_i;
input reset_i;
input v_i;
input enq_not_deq_i;
output full_o;
output empty_o;
wire [61:0] data_o;
  wire full_o,empty_o;
  reg [61:0] mem [0:63];
  reg [6:0] read_ptr,write_ptr;
  reg last_op;
  reg [61:0] data_o_var;
  assign data_o = data_o_var;
  assign full_o = (read_ptr == write_ptr && last_op == 1'b0);
  assign empty_o = (read_ptr == write_ptr && last_op == 1'b1);
  always @(posedge clk_i) begin
    if(1'b1) begin
      if(reset_i == 1'b1) begin
        read_ptr <= {6{1'b0}};
        write_ptr <= {6{1'b0}};
        last_op <= 1'b0;
      end else begin
        if(enq_not_deq_i == 1'b0) begin
          write_ptr <= write_ptr + 1;
          last_op <= 1'b0;
        end else begin
          read_ptr <= read_ptr + 1;
          last_op <= 1'b1;
        end
      end
    end
  end
  always @(posedge clk_i) begin
    if(1'b1) begin
      if(reset_i == 1'b1) begin
        data_o_var <= {62{1'b0}};
      end else if(v_i == 1'b1) begin
        if(enq_not_deq_i == 1'b0) begin
          data_o_var <= mem[write_ptr];
        end else begin
          data_o_var <= mem[read_ptr];
        end
      end
    end
  end
  always @(posedge clk_i) begin
    if(1'b1) begin
      if(reset_i == 1'b1) begin
        mem[write_ptr] <= {62{1'b0}};
      end else if(v_i == 1'b1) begin
        if(enq_not_deq_i == 1'b0) begin
          mem[write_ptr] <= data_i;
        end else begin
          mem[read_ptr] <= data_i;
        end
      end
    end
  end
endmodule

