parameter state1 = 3'b001;
parameter state2 = 3'b010;
parameter state3 = 3'b011;
parameter state4 = 3'b100;
parameter state5 = 3'b101;
parameter state6 = 3'b110;
parameter state7 = 3'b111;
always @(posedge clk or posedge reset)
begin
if (reset)
begin
state <= state0;
end
else
begin
case (state)
state0: begin
red <= 1'b1;
yellow <= 1'b0;
green <= 1'b0;
state <= state1;
end
state1: begin
red <= 1'b0;
yellow <= 1'b1;
green <= 1'b0;
state <= state2;
end
