red <= 1'b0;
yellow <= 1'b0;
green <= 1'b1;
state <= state3;
end
state3: begin
red <= 1'b0;
yellow <= 1'b0;
green <= 1'b0;
state <= state4;
end
state4: begin
red <= 1'b1;
yellow <= 1'b0;
green <= 1'b0;
state <= state5;
end
state5: begin
red <= 1'b0;
yellow <= 1'b1;
green <= 1'b0;
state <= state6;
