module lpm_or (
    data,  
    result 
);


    input  [(lpm_size * lpm_width)-1:0] data;


    output [lpm_width-1:0] result;
parameter lpm_width = 1;
    parameter lpm_size = 1;


    reg  [(lpm_width-1):0] result;

    initial begin
        if (lpm_width <= 0)
            $error("lpm_width = %0d is not valid", lpm_width);
        if (lpm_size <= 0)
            $error("lpm_size = %0d is not valid", lpm_size);
    end


    always @ (data)
    begin
        reg  [(lpm_width-1):0] temp;

        for (integer i = 0; i < lpm_size; i = i + 1)
            temp = temp | data[i * lpm_width +: lpm_width];

        result = temp;
    end


endmodule

