module zsignals
(
  input wire clk,
  input wire zpos,
  input wire rst_n,
  input wire iorq_n,
  input wire mreq_n,
  input wire m1_n,
  input wire rfsh_n,
  input wire rd_n,
  input wire wr_n,
  output wire rst,
  output wire m1,
  output wire rfsh,
  output wire rd,
  output wire wr,
  output wire iorq,
  output wire mreq,
  output wire rdwr,
  output wire iord,
  output wire iowr,
  output wire iordwr,
  output wire memrd,
  output wire memwr,
  output wire memrw,
  output wire opfetch,
  output wire intack,
  output wire iorq_s,
  output wire mreq_s,
  output wire iord_s,
  output wire iowr_s,
  output wire iordwr_s,
  output wire memrd_s,
  output wire memwr_s,
  output wire memrw_s,
  output wire opfetch_s
);
reg iorq_r, iorq_r_s;
  reg mreq_r, mreq_r_s;
  always @(posedge clk) begin
    if (!rst_n) begin
      iorq_r <= 1'b0;
      mreq_r <= 1'b0;
    end
    else begin
      if (zpos) begin
        iorq_r <= iorq_n;
        mreq_r <= mreq_n;
      end
    end
  end
  assign iorq = iorq_r;
  assign iorq_s = iorq_r_s;
  assign mreq = mreq_r;
  assign mreq_s = mreq_r_s;
  assign rst = iorq_r;
  assign m1 = m1_n;
  assign rfsh = rfsh_n;
  assign rd = rd_n;
  assign wr = wr_n;
  assign rdwr = rd_n & wr_n;
  assign iord = iorq_r & rd_n;
  assign iowr = iorq_r & wr_n;
  assign iordwr = iord & iowr;
  assign memrd = mreq_r & rd_n;
  assign memwr = mreq_r & wr_n;
  assign memrw = memrd & memwr;
  assign opfetch = mreq_r & rd_n & wr_n;
  assign intack = mreq_r & rd_n & wr_n & iorq_r;
  assign iord_s = iord_r_s;
  assign iowr_s = iowr_r_s;
  assign iordwr_s = iordwr_r_s;
  assign memrd_s = memrd_r_s;
  assign memwr_s = memwr_r_s;
  assign memrw_s = memrw_r_s;
  assign opfetch_s = opfetch_r_s;
  reg iorq_r_s, iorq_r_s_s;
  reg mreq_r_s, mreq_r_s_s;
  always @(posedge clk) begin
    if (!rst_n) begin
      iorq_r_s <= 1'b0;
      mreq_r_s <= 1'b0;
    end
    else begin
      if (zpos) begin
        iorq_r_s <= iorq_r;
        mreq_r_s <= mreq_r;
      end
    end
  end
  assign iorq_s = iorq_r_s;
  assign mreq_s = mreq_r_s;
  reg iord_r_s, iord_r_s_s;
  reg iowr_r_s, iowr_r_s_s;
  reg iordwr_r_s, iordwr_r_s_s;
  reg memrd_r_s, memrd_r_s_s;
  reg memwr_r_s, memwr_r_s_s;
  reg memrw_r_s, memrw_r_s_s;
  reg opfetch_r_s, opfetch_r_s_s;
  always @(posedge clk) begin
    if (!rst_n) begin
      iord_r_s <= 1'b0;
      iowr_r_s <= 1'b0;
      iordwr_r_s <= 1'b0;
      memrd_r_s <= 1'b0;
      memwr_r_s <= 1'b0;
      memrw_r_s <= 1'b0;
      opfetch_r_s <= 1'b0;
    end
    else begin
      if (zpos) begin
        iord_r_s <= iord_r;
        iowr_r_s <= iowr_r;
        iordwr_r_s <= iordwr_r;
        memrd_r_s <= memrd_r;
        memwr_r_s <= memwr_r;
        memrw_r_s <= memrw_r;
        opfetch_r_s <= opfetch_r;
      end
    end
  end
  assign iord_s = iord_r_s;
  assign iowr_s = iowr_r_s;
  assign iordwr_s = iordwr_r_s;
  assign memrd_s = memrd_r_s;
  assign memwr_s = memwr_r_s;
  assign memrw_s = memrw_r_s;
  assign opfetch_s = opfetch_r_s;
endmodule

