module uart_tx_tester ( input clk_50M, input run_test_raw, input tx_busy, output reg [7:0] data_out, output reg trigger );
localparam MSG_DELAY = 100000000;
    localparam LOAD_DATA = 2'b00;
    localparam START_TX = 2'b01;
    localparam POLL_BUSY = 2'b10;
    localparam PAUSE = 2'b11;
    reg [1:0] state;
    reg [7:0] data_pos;
    reg [31:0] delay;
    always @(posedge clk_50M) begin
        if (run_test_raw) begin
            state <= LOAD_DATA;
            data_pos <= 8'b00000000;
            delay <= 0;
        end
        else begin
            case (state)
                LOAD_DATA: begin
                    if (delay == 0) begin
                        data_out <= "Hello World! ";
                        data_pos <= 8'b00000000;
                        delay <= MSG_DELAY;
                        state <= START_TX;
                    end
                    else begin
                        delay <= delay - 1;
                    end
                end
                START_TX: begin
                    if (tx_busy) begin
                        state <= POLL_BUSY;
                    end
                    else begin
                        state <= PAUSE;
                    end
                end
                POLL_BUSY: begin
                    if (tx_busy) begin
                        state <= POLL_BUSY;
                    end
                    else begin
                        state <= PAUSE;
                    end
                end
                PAUSE: begin
                    if (delay == 0) begin
                        state <= LOAD_DATA;
                    end
                    else begin
                        delay <= delay - 1;
                    end
                end
            endcase
        end
    end
endmodule

