module maxFinder #(parameter numInput=10,parameter inputWidth=16)(
input           i_clk,
input [(numInput*inputWidth)-1:0]   i_data,
input           i_valid,
output reg [31:0]o_data,
output  reg     o_data_valid
);
reg [31:0] maxValue;
reg [31:0] inDataBuffer[(numInput*inputWidth)-1:0];
reg [31:0] counter;
always @(posedge i_clk) begin
    if (i_valid) begin
        counter <= 0;
        o_data_valid <= 0;
    end else begin
        if (counter == (numInput-1)) begin
            o_data_valid <= 1;
            o_data <= counter;
        end
        if (counter < (numInput-1)) begin
            maxValue <= inDataBuffer[counter];
            counter <= counter + 1;
        end
    end
end
always @(posedge i_clk) begin
    if (i_valid) begin
        for (counter = 0; counter < (numInput*inputWidth); counter = counter + 1) begin
            inDataBuffer[counter] <= i_data[counter];
        end
    end
end
endmodule

