module KEY_MUX
(
	input PS2_CLK,
	input PS2_DAT,
	output [9:0]LEDR,
	output [6:0]HEX0,
	output [6:0]HEX1
);
wire [7:0]scan_code;
	assign scan_code = keyboard(scan_code, PS2_CLK, PS2_DAT);

	assign LEDR[3:0] = S;
	assign LEDR[9:4] = NS;

	assign HEX0 = in1;
	assign HEX1 = in2;

	assign out = in3;

	reg [3:0]S, NS;
	reg [7:0]in1, in2, in3;

	always @(scan_code)
	begin
		case (S)
			4'b0000: begin
				in1 <= scan_code;
				in2 <= 8'b00000000;
				in3 <= 8'b00000000;
				S <= 4'b0001;
			end
			4'b0001: begin
				in1 <= 8'b00000000;
				in2 <= scan_code;
				in3 <= 8'b00000000;
				S <= 4'b0010;
			end
			4'b0010: begin
				in1 <= 8'b00000000;
				in2 <= 8'b00000000;
				in3 <= scan_code;
				S <= 4'b0011;
			end
			4'b0011: begin
				in1 <= 8'b00000000;
				in2 <= 8'b00000000;
				in3 <= 8'b00000000;
				S <= 4'b0100;
			end
			4'b0100: begin
				in1 <= 8'b00000000;
				in2 <= 8'b00000000;
				in3 <= 8'b00000000;
				S <= 4'b0000;
			end
		endcase
	end

	always @(S)
	begin
		case (S)
			4'b0000: begin
				NS <= 4'b0001;
			end
			4'b0001: begin
				NS <= 4'b0010;
			end
			4'b0010: begin
				NS <= 4'b0011;
			end
			4'b0011: begin
				NS <= 4'b0100;
			end
			4'b0100: begin
				NS <= 4'b0000;
			end
		endcase
	end

endmodule

