module db (
        input clk, n_reset, button_in,
        output reg out
    );
parameter maxbit = 16;
    reg [maxbit-1:0] q_reg, q_next;
    reg f1, f2;
    wire q_add, q_reset;
    always @(posedge clk or negedge n_reset) begin
        if (!n_reset) begin
            q_reg <= 0;
            f1 <= 0;
            f2 <= 0;
        end else begin
            f1 <= button_in;
            f2 <= f1;
            q_reg <= q_next;
        end
    end
    always @(posedge clk or negedge n_reset) begin
        if (!n_reset) begin
            q_next <= 0;
        end else begin
            q_next <= q_reg + q_add;
            q_reset <= q_reg == q_next;
        end
    end
    assign q_add = q_reset ? 0 : f2;
    assign q_reset = q_reg == q_next;
    always @(posedge clk or negedge n_reset) begin
        if (!n_reset) begin
            out <= 0;
        end else begin
            out <= q_reg == q_next ? f2 : 0;
        end
    end
endmodule

