module jk_flop (input J, K, clk,
                output reg Q, Qbar);
always @(posedge clk)
    begin
        if (J & K)
            Q <= ~Q;
        else if (J)
            Q <= 1;
        else if (K)
            Q <= 0;
    end
    assign Qbar = ~Q;
endmodule

module Walk2R_example (
	input logic vga_clk,
	input logic [9:0] DrawX, DrawY,
	input logic blank,
	output logic [3:0] red, green, blue
);
logic [12:0] rom_address;
logic [7:0] rom_q;

logic [3:0] palette_red, palette_green, palette_blue;

logic negedge_vga_clk;


assign negedge_vga_clk = ~vga_clk;







assign rom_address = (DrawX*16)/640 + (((DrawY*16)/480) * 16);

always_ff @ (posedge vga_clk) begin

	red <= 4'h0;
	green <= 4'h0;
	blue <= 4'h0;

	if (blank) begin
		red <= palette_red;
		green <= palette_green;
		blue <= palette_blue;
	end
end

Walk2R_rom Walk2R_rom (
	.clock   (negedge_vga_clk),
	.address (rom_address),
	.q       (rom_q)
);

Walk2R_palette Walk2R_palette (
	.index (rom_q),
	.red   (palette_red),
	.green (palette_green),
	.blue  (palette_blue)
);

endmodule

