module I_SQRT_2(
input wire [31:0] n,
input wire CLK,
input wire RST_n,
input wire EN,
input wire SEL,
output wire VAL,
output wire Z,
output wire [31:0] out_sqrt
); 

reg [31:0] x_0 = 32'h00000001;
reg [31:0] x_i;
reg [31:0] x_i_mux;
reg [31:0] x_next;
reg [31:0] sqrt;
reg val_comb;
reg z_comb;
reg val_ff;
reg z_ff;
reg [31:0] out_sqrt_reg;
  always @(posedge CLK, posedge RST_n) begin
    if((RST_n == 1'b0)) begin
      x_0 <= 32'h00000001;
      x_i <= 32'h00000001;
      x_i_mux <= 32'h00000001;
      x_next <= 32'h00000001;
      sqrt <= 32'h00000000;
      val_comb <= 1'b0;
      z_comb <= 1'b0;
      val_ff <= 1'b0;
      z_ff <= 1'b0;
      out_sqrt_reg <= 32'h00000000;
    end else begin
      x_i_mux <= x_i;
      x_next <= x_i + (n / x_i);
      if((x_next >= x_i)) begin
        sqrt <= x_i;
        val_comb <= 1'b1;
        z_comb <= 1'b0;
      end
      else begin
        val_comb <= 1'b0;
        z_comb <= 1'b0;
      end
      if((EN == 1'b1)) begin
        val_ff <= val_comb;
        z_ff <= z_comb;
        out_sqrt_reg <= sqrt;
      end
    end
  end
  assign VAL = val_ff;
  assign Z = z_ff;
  assign out_sqrt = out_sqrt_reg;
endmodule

