module barrel_shifter_tb;
reg [7:0] in;
	reg [3:0] shift;
	reg [3:0] control;
	wire [7:0] out;
	reg [7:0] expected;
	integer error_count = 0;

	barrel_shifter uut (
		.in(in), 
		.shift(shift), 
		.control(control), 
		.out(out)
	);

	initial begin
		in = 128;
		shift = 4;
		control = 0;
		expected = 64;
		#1;
		if (out !== expected) begin
			$display("FAIL: shift by %d, in = %d, control = %d, out = %d, expected = %d", shift, in, control, out, expected);
			error_count = error_count + 1;
		end
		else begin
			$display("PASS: shift by %d, in = %d, control = %d, out = %d, expected = %d", shift, in, control, out, expected);
		end

		in = 128;
		shift = 2;
		control = 0;
		expected = 32;
		#1;
		if (out !== expected) begin
			$display("FAIL: shift by %d, in = %d, control = %d, out = %d, expected = %d", shift, in, control, out, expected);
			error_count = error_count + 1;
		end
		else begin
			$display("PASS: shift by %d, in = %d, control = %d, out = %d, expected = %d", shift, in, control, out, expected);
		end

		in = 128;
		shift = 1;
		control = 0;
		expected = 64;
		#1;
		if (out !== expected) begin
			$display("FAIL: shift by %d, in = %d, control = %d, out = %d, expected = %d", shift, in, control, out, expected);
			error_count = error_count + 1;
		end
		else begin
			$display("PASS: shift by %d, in = %d, control = %d, out = %d, expected = %d", shift, in, control, out, expected);
		end

		in = 255;
		shift = 7;
		control = 0;
		expected = 1;
		#1;
		if (out !== expected) begin
			$display("FAIL: shift by %d, in = %d, control = %d, out = %d, expected = %d", shift, in, control, out, expected);
			error_count = error_count + 1;
		end
		else begin
			$display("PASS: shift by %d, in = %d, control = %d, out = %d, expected = %d", shift, in, control, out, expected);
		end

		if (error_count == 0) begin
			$display("All tests passed!");
		end
		else begin
			$display("%d tests failed!", error_count);
		end
	end
