module SCK_control_slave( input wire SCK_in, input wire CPOL, input wire CPHA, input wire idle, output reg S_BaudRate, output wire Shift_clk, output wire Sample_clk );
reg Shift_clk, Sample_clk;
    always @( SCK_in, CPOL, CPHA, idle, S_BaudRate ) begin
        case (CPOL & CPHA)
            2'b00: begin
                Shift_clk = ~idle & S_BaudRate;
                Sample_clk = ~idle & ~S_BaudRate;
            end
            2'b01: begin
                Shift_clk = idle & S_BaudRate;
                Sample_clk = idle & ~S_BaudRate;
            end
            2'b10: begin
                Shift_clk = idle & S_BaudRate;
                Sample_clk = idle & ~S_BaudRate;
            end
            2'b11: begin
                Shift_clk = ~idle & S_BaudRate;
                Sample_clk = ~idle & ~S_BaudRate;
            end
        endcase
    end
    assign S_BaudRate = (SCK_in == 1'b1) ? 1'b1 : 1'b0;
    assign Shift_clk = (Shift_clk == 1'b1) ? 1'b1 : 1'b0;
    assign Sample_clk = (Sample_clk == 1'b1) ? 1'b1 : 1'b0;
endmodule

