module serial(clk, reset, rxD,sout,signal,counter);
input clk;      
input reset;    
input rxD;   

output reg [n-1:0]sout; 
output reg signal;   
output reg [31:0]counter;
parameter n = 30;
parameter count = 4;

reg [2:0]delay;

top top(.clk(clk),.reset(reset),.rxD(rxD),.s_in(s_in),.sout(sout));

always @(posedge clk) begin
    if (reset) begin
        counter <= 0;
        signal <= 0;
    end
    else begin
        if (counter == count) begin
            signal <= 1;
            delay <= 1;
        end
        else begin
            signal <= 0;
            delay <= 0;
        end
        if (delay == 1) begin
            counter <= counter + 1;
        end
        else begin
            counter <= 0;
        end
    end
end

endmodule

