endmodule

module arbiter (
clock, 
reset, 
req_0,
req_1, 
gnt_0,
gnt_1
);

input clock, reset, req_0, req_1;
output gnt_0, gnt_1;
reg gnt_0, gnt_1;

always @(posedge clock) begin
	if (reset) begin
		gnt_0 <= 0;
		gnt_1 <= 0;
	end
	else begin
		if (req_0) begin
			gnt_0 <= 1;
			gnt_1 <= 0;
		end
		else if (req_1) begin
			gnt_0 <= 0;
			gnt_1 <= 1;
		end
		else begin
			gnt_0 <= 0;
			gnt_1 <= 0;
		end
	end
end

endmodule

module NAND3C(Y,A,B,C);
 input A,B,C;
 output Y;
wire A__bar,B__bar;

 not	INV_1_0(A__bar,A);
 not	INV_1_1(B__bar,B);

 and      U165(A__bar__bar,B__bar,A__bar);
 nand     U166(Y,A__bar__bar,C);

