module chose(output reg [17:0]choout,
				input [16:0]choin,
				input resreg,
				input clk);
reg [16:0]chotmp;
	always @(posedge clk)
		begin
			if(resreg==0)
				begin
					choout[16:0]=choin[16:0];
					choout[17]=choin[16];
				end
			else
				begin
					chotmp[16:0]=~choin[16:0];
					chotmp[16:0]=chotmp[16:0]+1;
					choout[16:0]=chotmp[16:0];
					choout[17]=~choin[16];
				end
		end
endmodule

