      for (i = 0; i < numOfCounters; i = i + 1) begin : genCounter
         NBitCounter #(
            .counterSize(counterSize)
         ) counter (
            .clk(clk),
            .reset(reset),
            .count(counts[i]),
            .enable(enable[i]),
            .outCount(counts[i+1])
         );
