module division(A,B,Res);
    input [WIDTH-1:0] A;
    input [WIDTH-1:0] B;

    output reg [WIDTH-1:0] Res = 0;
parameter WIDTH = 16;

    reg [WIDTH-1:0] a1;
    reg [WIDTH-1:0] b1;
    reg [WIDTH:0] p1;
    integer i;
    always @(A or B)
    begin
        a1 = A;
        b1 = B;
        p1 = {1'b0,A};
        for(i=0;i<WIDTH;i=i+1)
        begin
            if(p1[WIDTH-1:WIDTH-i] >= b1)
            begin
                p1 = p1 - b1;
                Res[i] = 1'b1;
            end
            else
                Res[i] = 1'b0;
            p1 = {p1[WIDTH-1:0],1'b0};
        end
    end
endmodule

