module vga_sync(
input wire clk,
input wire rst,
output reg active,
output reg hsync,
output reg vsync,
output wire [9:0] xaddr,
output wire [9:0] yaddr
); 

parameter [31:0] HRES=640;
parameter [31:0] VRES=480;
parameter [31:0] HBLANK=16;
parameter [31:0] VBLANK=4;
parameter [31:0] HRETRACE=16;
parameter [31:0] VRETRACE=16;
reg [9:0] h_count_reg;
reg [9:0] v_count_reg;
  always @(posedge clk) begin
    if(rst == 1'b1) begin
      h_count_reg <= {10{1'b0}};
      v_count_reg <= {10{1'b0}};
    end
    else begin
      h_count_reg <= h_count_reg + 1;
      v_count_reg <= v_count_reg + 1;
    end
  end
  assign xaddr = h_count_reg;
  assign yaddr = v_count_reg;
  always @(h_count_reg, v_count_reg) begin
    if((h_count_reg >= (HRES - HBLANK - HRETRACE)) && (v_count_reg >= (VRES - VBLANK - VRETRACE))) begin
      active <= 1'b1;
    end
    else begin
      active <= 1'b0;
    end
  end
  always @(h_count_reg, v_count_reg) begin
    if((h_count_reg >= (HRES - HBLANK - HRETRACE)) && (v_count_reg >= (VRES - VBLANK - VRETRACE))) begin
      hsync <= 1'b0;
    end
    else begin
      hsync <= 1'b1;
    end
  end
  always @(h_count_reg, v_count_reg) begin
    if((h_count_reg >= (HRES - HBLANK - HRETRACE)) && (v_count_reg >= (VRES - VBLANK - VRETRACE))) begin
      vsync <= 1'b0;
    end
    else begin
      vsync <= 1'b1;
    end
  end
endmodule

