    reg [1:0] state;
    reg [1:0] next_state;
    always @(posedge clk) begin
        if (areset) begin
            walk <= 1'b0;
            state <= 2'b00;
        end else begin
            walk <= next_state[0];
            state <= next_state[1];
        end
    end
    always @(state, bump_left, bump_right) begin
        next_state[0] = walk;
        next_state[1] = state;
        case (state)
            2'b00: begin
                next_state[0] = 1'b0;
                next_state[1] = 2'b01;
                if (bump_left) begin
                    next_state[0] = 1'b1;
                    next_state[1] = 2'b10;
                end
                if (bump_right) begin
                    next_state[0] = 1'b0;
                    next_state[1] = 2'b11;
                end
            end
            2'b01: begin
                next_state[0] = 1'b1;
                next_state[1] = 2'b00;
                if (bump_left) begin
                    next_state[0] = 1'b0;
                    next_state[1] = 2'b10;
                end
                if (bump_right) begin
                    next_state[0] = 1'b1;
                    next_state[1] = 2'b11;
                end
            end
            2'b10: begin
                next_state[0] = 1'b0;
                next_state[1] = 2'b01;
                if (bump_left) begin
                    next_state[0] = 1'b1;
                    next_state[1] = 2'b11;
                end
                if (bump_right) begin
                    next_state[0] = 1'b0;
                    next_state[1] = 2'b10;
                end
            end
            2'b11: begin
                next_state[0] = 1'b1;
                next_state[1] = 2'b00;
                if (bump_left) begin
                    next_state[0] = 1'b0;
                    next_state[1] = 2'b10;
                end
                if (bump_right) begin
                    next_state[0] = 1'b1;
                    next_state[1] = 2'b11;
                end
            end
            default: begin
                next_state[0] = 1'b0;
                next_state[1] = 2'b00;
