            f_reg <= 1'b0;
            g_reg <= 1'b0;
        end else begin
            case (state)
                2'b00: begin
                    f_reg <= 1'b0;
                    g_reg <= 1'b0;
                    state <= 2'b01;
                end
                2'b01: begin
                    f_reg <= 1'b1;
                    g_reg <= 1'b0;
                    state <= 2'b10;
                end
                2'b10: begin
                    if (x == 1'b1) begin
                        f_reg <= 1'b1;
                        g_reg <= 1'b1;
                        state <= 2'b11;
                    end else if (x == 1'b0) begin
                        f_reg <= 1'b1;
                        g_reg <= 1'b0;
                        state <= 2'b11;
                    end else begin
                        f_reg <= 1'b1;
                        g_reg <= 1'b0;
                        state <= 2'b10;
                    end
                end
                2'b11: begin
                    if (y == 1'b1) begin
                        f_reg <= 1'b1;
                        g_reg <= 1'b1;
                        state <= 2'b11;
                    end else begin
                        f_reg <= 1'b1;
                        g_reg <= 1'b0;
                        state <= 2'b11;
                    end
                end
                default: begin
                    f_reg <= 1'b0;
                    g_reg <= 1'b0;
                    state <= 2'b00;
                end
            endcase
        end
    end
    assign f = f_reg;
    assign g = g_reg;
endmodule

