module TopModule(
    input  clk,
    input  load,
    input  [255:0] data,
    output reg [255:0] q
);
localparam ROWS = 16;
    localparam COLS = 16;
    localparam NEIGHBORS = 8;

    always @(posedge clk) begin
        if (load) begin
            q <= data;
        end else begin
            for (int i = 0; i < ROWS; i = i + 1) begin
                for (int j = 0; j < COLS; j = j + 1) begin
                    int count = 0;
                    for (int k = 0; k < NEIGHBORS; k = k + 1) begin
                        int i2 = (i + k / COLS) % ROWS;
                        int j2 = (j + k % COLS) % COLS;
                        count = count + q[i2 * COLS + j2];
                    end
                    if (count == 0) begin
                        q[i * COLS + j] <= 0;
                    end else if (count == 1) begin
                        q[i * COLS + j] <= 0;
                    end else if (count == 2) begin
                        q[i * COLS + j] <= q[i * COLS + j];
                    end else if (count == 3) begin
                        q[i * COLS + j] <= 1;
                    end else begin
                        q[i * COLS + j] <= 0;
                    end
                end
            end
        end
    end

endmodule

