module TopModule(
    input  clk,
    input  reset,
    input  data,
    output reg [3:0] count,
    output reg counting,
    output reg done,
    input  ack
);
reg [3:0] delay;
    always @(posedge clk) begin
        if (reset) begin
            count <= 4'b0000;
            counting <= 1'b0;
            done <= 1'b0;
        end else begin
            if (data == 4'b1101) begin
                count <= 4'b0000;
                counting <= 1'b1;
                done <= 1'b0;
            end else if (counting) begin
                count <= count + 1;
                if (count == (delay + 1)) begin
                    counting <= 1'b0;
                    done <= 1'b1;
                end
            end else if (ack) begin
                counting <= 1'b0;
                done <= 1'b0;
            end
        end
    end
    always @(posedge clk) begin
        if (reset) begin
            delay <= 4'b0000;
        end else begin
            if (counting) begin
                delay <= delay + 1;
            end
        end
    end
endmodule

