module TopModule (
  input clk,
  input [7:0] in,
  input reset,
  output done
);
reg [2:0] state;
  reg [7:0] byte;
  reg done_reg;
  always @(posedge clk) begin
    if (reset) begin
      state <= 3'b000;
      byte <= 8'b00000000;
      done_reg <= 1'b0;
    end else begin
      if (state == 3'b000) begin
        if (in[3]) begin
          byte <= in;
          state <= 3'b001;
        end
      end else if (state == 3'b001) begin
        if (in[3]) begin
          byte <= in;
          state <= 3'b010;
        end
      end else if (state == 3'b010) begin
        if (in[3]) begin
          byte <= in;
          state <= 3'b011;
        end
      end else if (state == 3'b011) begin
        if (in[3]) begin
          byte <= in;
          state <= 3'b100;
        end
      end else if (state == 3'b100) begin
        if (in[3]) begin
          byte <= in;
          state <= 3'b101;
        end
      end else if (state == 3'b101) begin
        if (in[3]) begin
          byte <= in;
          state <= 3'b110;
        end
      end else if (state == 3'b110) begin
        if (in[3]) begin
          byte <= in;
          state <= 3'b111;
        end
      end else if (state == 3'b111) begin
        if (in[3]) begin
          byte <= in;
          state <= 3'b000;
        end
      end
    end
  end
  always @(posedge clk) begin
    if (reset) begin
      done_reg <= 1'b0;
    end else begin
      if (state == 3'b111) begin
        done_reg <= 1'b1;
      end else begin
        done_reg <= 1'b0;
      end
    end
  end
  assign done = done_reg;
endmodule

module TopModule (
