  reg [1:0] state, next;
  always @(posedge clk or negedge aresetn) begin
    if (!aresetn) begin
      state <= S0;
    end
    else begin
      state <= next;
    end
  end
  always @(*) begin
    case (state)
      S0: if (x) next = S1;
      S1: if (x) next = S2;
      S2: if (x) next = S3;
      S3: if (x) next = S3;
      default: next = S0;
    endcase
  end
  always @(*) begin
    case (state)
      S0: z = 1'b0;
      S1: z = 1'b0;
      S2: z = 1'b0;
      S3: z = 1'b1;
